import { Router } from 'express';
import { createReadStream } from 'node:fs';
import path from 'node:path';
import { requireAuth } from '../middleware/requireAuth';

const STORAGE_ROOT = '/srv/documents';

export const documentRouter = Router();

documentRouter.get('/documents/download', requireAuth, (req, res) => {
  const name = String(req.query.name ?? '');
  const absolute = path.join(STORAGE_ROOT, name);

  res.setHeader('Content-Disposition', `attachment; filename="${path.basename(name)}"`);
  return createReadStream(absolute).pipe(res);
});

