import { Router } from 'express';
import { createReadStream } from 'node:fs';
import { requireAuth } from '../middleware/requireAuth';
import { resolveDocument } from '../services/storage';

export const documentRouter = Router();

documentRouter.get('/documents/:id/download', requireAuth, async (req, res) => {
  const document = await resolveDocument(Number(req.params.id), req.user.accountId);

  if (!document) {
    return res.status(404).json({ error: 'Document not found' });
  }

  res.setHeader('Content-Disposition', `attachment; filename="${document.displayName}"`);
  return createReadStream(document.absolutePath).pipe(res);
});

