import path from 'node:path';
import { db } from '../db';

const STORAGE_ROOT = '/srv/documents';

export interface StoredDocument {
  id: number;
  accountId: number;
  displayName: string;
  absolutePath: string;
}

export async function resolveDocument(
  id: number,
  accountId: number,
): Promise<StoredDocument | null> {
  const [row] = await db.query(
    'select id, account_id, display_name, storage_key from documents where id = $1 and account_id = $2',
    [id, accountId],
  );
  if (!row) return null;

  return {
    id: row.id,
    accountId: row.account_id,
    displayName: row.display_name,
    absolutePath: path.join(STORAGE_ROOT, String(row.id), row.storage_key),
  };
}
